mapper.select:
SELECT ${sqlMap.column.toSql()}
FROM ${sqlMap.table.toSql()}
WHERE warning_time >= DATE_SUB(CURDATE(), INTERVAL 7 DAY)
AND warning_time < DATE_ADD(CURDATE(), INTERVAL 1 DAY)
AND status = '0'

SELECT ${sqlMap.column.toSql()}
FROM ${sqlMap.table.toSql()}
WHERE warning_time >= CURDATE()
AND warning_time < (CURDATE(), INTERVAL 1 DAY)
AND status = '0'
